mapper.select:
SELECT *
FROM reconciliation_cutoff
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND cutoff_id=#{cutoffId} FOR UPDATE

SELECT f.id, f.source_service, f.command_id, f.quantity, f.occurred_at, p.id AS other_id, p.quantity AS other_qty
FROM source_execution_fact f LEFT JOIN stock_posting p ON p.enterprise_id=f.enterprise_id AND p.warehouse_id=f.warehouse_id
    AND p.source_service=f.source_service AND p.command_id=f.command_id AND p.created_at < #{cutoff}
WHERE f.enterprise_id=#{enterpriseId} AND f.warehouse_id=#{warehouseId} AND f.fact_kind='PHYSICAL' AND f.occurred_at < #{cutoff}
AND f.id > #{cursor}
ORDER BY f.id LIMIT #{limit}

SELECT p.id, p.source_service, p.command_id, p.quantity, f.id AS other_id
FROM stock_posting p LEFT JOIN source_execution_fact f ON f.enterprise_id=p.enterprise_id AND f.warehouse_id=p.warehouse_id
    AND f.source_service=p.source_service AND f.command_id=p.command_id AND f.fact_kind='PHYSICAL' AND f.occurred_at < #{cutoff}
WHERE p.enterprise_id=#{enterpriseId} AND p.warehouse_id=#{warehouseId} AND p.created_at < #{cutoff}
AND p.id > #{cursor}
ORDER BY p.id LIMIT #{limit}

mapper.update:
UPDATE reconciliation_scan SET balance_cursor=#{scan.balance_cursor},fact_cursor=#{scan.fact_cursor},posting_cursor=#{scan.posting_cursor},
    balance_done=#{scan.balance_done},fact_done=#{scan.fact_done},posting_done=#{scan.posting_done},
    completed_cycles=completed_cycles+#{completed},version=version+1,updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND cutoff_id=#{cutoffId} AND version=#{scan.version}

